import {THREE} from './lib/core.js';
// Original rounded, multi-part scenery. Coordinates keep decoration behind the playable lane.
export function createWorldArt(){
 const animated=[];
 const mat=(color,extra={})=>new THREE.MeshStandardMaterial({color,roughness:.52,...extra});
 const green=mat(0x1ebd60),cream=mat(0xfff2d0),red=mat(0xf75057),gold=mat(0xffd34e,{metalness:.35,roughness:.25});
 function mesh(g,geo,m,x,y,z){const o=new THREE.Mesh(geo,m);o.position.set(x,y,z);o.castShadow=o.receiveShadow=true;o.userData.cleanArt=true;g.add(o);return o}
 function ball(g,x,y,z,r,m,s=[1,1,1]){const o=mesh(g,new THREE.SphereGeometry(r,16,12),m,x,y,z);o.scale.set(...s);return o}
 function tube(g,x,y,z,r,h,m){return mesh(g,new THREE.CylinderGeometry(r,r,h,24),m,x,y,z)}
 function mushroom(g,x,y,z,size=1){const root=new THREE.Group();root.position.set(x,y,z);root.scale.setScalar(size);g.add(root);tube(root,0,.43,0,.27,.86,cream);const cap=ball(root,0,.95,0,.8,red,[1,.55,1]);for(const a of [-1.8,-.4,.8,2.3])ball(root,Math.cos(a)*.53,1.2,Math.sin(a)*.53,.16,cream,[1,.26,1]);for(const a of [-.1,.1])ball(root,a,.5,.255,.045,mat(0x252b40),[.7,1.8,.5]);return root}
 function pipe(g,x,y,z,h=1.6){const root=new THREE.Group();root.position.set(x,y,z);g.add(root);tube(root,0,h/2,0,.58,h,green);tube(root,0,h,0,.74,.3,green);tube(root,0,h+.153,0,.57,.015,mat(0x103b2a));tube(root,0,h+.165,0,.45,.018,mat(0x08281f));return root}
 function star(g,x,y,z,size=.4){const shape=new THREE.Shape();for(let i=0;i<10;i++){const a=Math.PI/2+i*Math.PI/5,r=i%2?.46:1;const px=Math.cos(a)*r,py=Math.sin(a)*r;if(i===0)shape.moveTo(px,py);else shape.lineTo(px,py)}shape.closePath();const root=new THREE.Group();root.position.set(x,y,z);root.scale.setScalar(size);g.add(root);mesh(root,new THREE.ExtrudeGeometry(shape,{depth:.18,bevelEnabled:true,bevelSize:.07,bevelThickness:.06,bevelSegments:2,steps:1}),gold,0,0,0);for(const dx of [-.22,.22])ball(root,dx,.12,.26,.08,mat(0x292c42),[.5,1.5,.4]);animated.push({root,base:y,kind:'star'});return root}
 function flower(g,x,y,z,c){const petal=mat(c);tube(g,x,y+.16,z,.025,.32,green);for(let i=0;i<5;i++){const a=i*Math.PI*2/5;ball(g,x+Math.cos(a)*.11,y+.35+Math.sin(a)*.11,z,.085,petal,[1,1,.45])}ball(g,x,y+.35,z+.04,.075,gold)}
 function tower(g,x,y,z,scale=1){const root=new THREE.Group();root.position.set(x,y,z);root.scale.setScalar(scale);g.add(root);const stone=mat(0xffe8cc),roof=mat(0xf16b85);tube(root,0,1.4,0,.7,2.8,stone);tube(root,0,2.68,0,.81,.25,cream);mesh(root,new THREE.ConeGeometry(.95,1.4,24),roof,0,3.48,0);tube(root,0,4.28,0,.025,.8,gold);const banner=mesh(root,new THREE.PlaneGeometry(.65,.35,8,2),mat(0xe84c63,{side:THREE.DoubleSide}),.32,4.42,0);animated.push({root:banner,kind:'flag'});for(const dz of [-.69,.69])mesh(root,new THREE.BoxGeometry(.28,.6,.07),mat(0x79b9d8),0,1.7,dz);return root}
 function map(g){for(let i=0;i<3;i++){const x=i*12;mushroom(g,x-2,.35,1.5,.8);pipe(g,x+2,.35,1.3,1+i*.25);star(g,x,3.3,-1.5,.38);for(let f=0;f<8;f++)flower(g,x-2.6+f*.7,.35,2.7,f%2?0xff9eca:0xffffff)}tower(g,24,0,-2,1.2);for(const x of [-3,3])tower(g,x,0,-3,.65)}
 function level(g,n){for(const x of [3,13,24,37])mushroom(g,x,.1,-4,.8+(x%3)*.2);for(const x of [7,22,40])pipe(g,x,-.2,-3,1.2+(x%3)*.35);for(let i=0;i<28;i++)flower(g,i*1.65,.1,-2.2,i%3===0?0xfeb4dc:i%3===1?0xffffff:0xffe85c);tower(g,47,-.3,-4,n===3?1.5:.9);star(g,47,6.2,0,.45);for(const x of [5,17,32]){const root=new THREE.Group();root.position.set(x,7,-10);g.add(root);for(const dx of [-.8,0,.8])ball(root,dx,dx===0?.2:0,0,.8,mat(0xffffff),[1,.7,.65]);animated.push({root,base:7,kind:'cloud'})}}
 function styleHero(hero){hero.userData.character.traverse(o=>{if(!o.isMesh)return;const materials=Array.isArray(o.material)?o.material:[o.material];o.material=materials.map(m=>{const next=new THREE.MeshPhysicalMaterial();THREE.MeshStandardMaterial.prototype.copy.call(next,m);next.roughness=.62;next.clearcoat=.18;next.clearcoatRoughness=.65;if(next.normalMap)next.normalScale.set(.35,.35);next.needsUpdate=true;return next});if(o.material.length===1)o.material=o.material[0]})}
 function update(t){for(const a of animated){if(!a.root.parent)continue;if(a.kind==='star'){a.root.rotation.y=t*.85;a.root.position.y=a.base+Math.sin(t*2)*.13}else if(a.kind==='flag'){const p=a.root.geometry.attributes.position;for(let i=0;i<p.count;i++)p.setZ(i,Math.sin(t*3+p.getX(i)*6)*.06*(p.getX(i)+.325));p.needsUpdate=true;a.root.geometry.computeVertexNormals()}else a.root.position.y=a.base+Math.sin(t*.4+a.root.position.x)*.15}}
 function clearLevel(){for(let i=animated.length-1;i>=0;i--)if(animated[i].root.parent?.parent?.name==='level-art'||animated[i].root.parent?.name==='level-art')animated.splice(i,1)}
 return {map,level,update,styleHero,clearLevel};
}
